{
  "predictors": [
    {
      "name": "Recent Dividend Initiation",
      "construction": "Identify firms that have initiated dividends within the past fiscal year using COMPUSTAT data.",
      "rationale": "Firms initiating dividends may signal strong future cash flows and managerial confidence.",
      "higher_returns_for": "Firms that have recently initiated dividends."
    },
    {
      "name": "Employee Growth Rate",
      "construction": "Calculate the annual growth rate in the number of employees from COMPUSTAT's employment data over the last three years.",
      "rationale": "Rapidly growing employee counts can indicate firm expansion and confidence in future growth prospects.",
      "higher_returns_for": "Firms with high employee growth rates."
    },
    {
      "name": "R&D to Asset Change Ratio",
      "construction": "Compute the change in R&D expenditure divided by the total assets from the previous year using COMPUSTAT data.",
      "rationale": "Increased R&D spending relative to assets may signal future innovation and growth potential.",
      "higher_returns_for": "Firms with high increases in R&D relative to assets."
    },
    {
      "name": "Off-Balance Sheet Leverage",
      "construction": "Estimate off-balance-sheet liabilities by analyzing footnotes in financial reports and compare them to on-balance-sheet debt.",
      "rationale": "Hidden leverage may indicate higher risk which could demand a risk premium in returns.",
      "higher_returns_for": "Firms with higher off-balance-sheet leverage."
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Track the growth in the number of citations of a firm's patents over the past three years using USPTO data.",
      "rationale": "Increasing patent citations reflect valuable intellectual property and innovation credentials.",
      "higher_returns_for": "Firms with high patent citation growth."
    },
    {
      "name": "Supplier Concentration Index",
      "construction": "Calculate the percentage of purchases from top suppliers as a ratio of total purchases using COMPUSTAT segment data.",
      "rationale": "Firms relying on fewer suppliers might negotiate better terms or face higher risk, potentially affecting returns.",
      "higher_returns_for": "Firms with low supplier concentration."
    },
    {
      "name": "Historical Tax Rate Variability",
      "construction": "Measure the standard deviation of the effective tax rate over the past five years using COMPUSTAT data.",
      "rationale": "Stable tax rates might reflect consistent profitability and favorable tax management strategies.",
      "higher_returns_for": "Firms with low variability in historical tax rates."
    },
    {
      "name": "Sentiment-Adjusted Insider Trading",
      "construction": "Net insider buying activity adjusted by sentiment analysis of news articles using LexisNexis data.",
      "rationale": "Insider buying coupled with positive news sentiment suggests confidence in future performance.",
      "higher_returns_for": "Firms with high sentiment-adjusted insider trading."
    },
    {
      "name": "Inventory Method Impact",
      "construction": "Determine the impact of changes in inventory valuation method (e.g., LIFO to FIFO) on reported earnings using footnotes.",
      "rationale": "Changes in inventory accounting may affect reported earnings and investors’ perception of firm value.",
      "higher_returns_for": "Firms benefiting positively from inventory method changes."
    },
    {
      "name": "Geographic Revenue Diversity",
      "construction": "Calculate the Herfindahl-Hirschman Index of revenue shares across different geographic regions from COMPUSTAT segment data.",
      "rationale": "Diversified geographic revenue streams can reduce firm-specific risk and enhance growth stability.",
      "higher_returns_for": "Firms with high geographic revenue diversity."
    }
  ]
}
